const WEIGHTS = {
  personalized: 0.44,
  objective: 0.12,
  budget: 0.20,
  runnerWeight: 0.03,
  distance: 0.07,
  foot: 0.02,
  strike: 0.01,
  brand: 0.01,
  foulee: 0.10
};

const PRIORITY_COEFS = [1.5, 1.25, 1.1];

const OBJECTIVE_TYPE = {
  "ENTRAÎNEMENT": {"DAILY":100,"TEMPO":75,"MAX CUSHION":90,"RACE":35,"POLYVALENTE":95},
  "CONFORT": {"DAILY":90,"TEMPO":65,"MAX CUSHION":100,"RACE":30,"POLYVALENTE":85},
  "POLYVALENT": {"DAILY":95,"TEMPO":100,"MAX CUSHION":75,"RACE":70,"POLYVALENTE":100},
  "PERFORMANCE": {"DAILY":70,"TEMPO":100,"MAX CUSHION":50,"RACE":95,"POLYVALENTE":85},
  "COMPÉTITION": {"DAILY":40,"TEMPO":80,"MAX CUSHION":25,"RACE":100,"POLYVALENTE":70}
};

const CRITERIA = [
  ["AMORTI","amorti"],
  ["DYNAMISME","dynamisme"],
  ["STABILITE","stabilite"],
  ["CONFORT","confort"],
  ["DURABILITE","durabilite"],
  ["LÉGÈRETÉ","legerete"]
];

const $ = (sel, root=document) => root.querySelector(sel);
const $$ = (sel, root=document) => [...root.querySelectorAll(sel)];

function normalizeText(s) {
  return String(s ?? "")
    .toUpperCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"");
}

$$(".question").forEach(question => {
  const buttons = $$(".option", question);
  buttons.forEach(button => {
    button.addEventListener("click", () => {
      buttons.forEach(b => b.classList.remove("selected"));
      button.classList.add("selected");
    });
  });
});

function selectedValue(key) {
  const q = $(`.question[data-key="${key}"]`);
  const btn = q ? $(".option.selected", q) : null;
  return btn ? btn.dataset.value : "";
}

function profileFromForm() {
  return {
    budget: Number($("#budget").value),
    objectif: selectedValue("objectif"),
    distance: selectedValue("distance"),
    poids: Number($("#poids").value),
    typePied: selectedValue("typePied"),
    attaque: selectedValue("attaque"),
    foulee: selectedValue("foulee"),
    pointure: Number($("#pointure").value),
    rayon: selectedValue("rayon"),
    priorite1: selectedValue("priorite1"),
    priorite2: selectedValue("priorite2"),
    priorite3: selectedValue("priorite3"),
    marque: selectedValue("marque")
  };
}

function validateProfile(p) {
  if (!p.budget || !p.objectif || !p.distance || !p.poids ||
      !p.typePied || !p.attaque || !p.foulee || !p.pointure || !p.rayon || !p.priorite1 || !p.priorite2 ||
      !p.priorite3 || !p.marque) {
    return "Merci de compléter toutes les informations avant de lancer le calcul.";
  }
  if (new Set([p.priorite1,p.priorite2,p.priorite3]).size !== 3) {
    return "Les priorités n°1, n°2 et n°3 doivent être différentes.";
  }
  if (p.budget < 50 || p.budget > 500) return "Entre un budget compris entre 50 € et 500 €.";
  if (p.poids < 40 || p.poids > 200) return "Entre un poids compris entre 40 kg et 200 kg.";
  if (p.pointure < 35 || p.pointure > 50 || Math.abs(p.pointure * 2 - Math.round(p.pointure * 2)) > 0.001) return "Entre une pointure comprise entre 35 et 50, par demi-pointure.";
  return "";
}

function personalizedScore(shoe,p) {
  const priorities = [p.priorite1,p.priorite2,p.priorite3];
  let numerator = 0;
  let denominator = 0;
  CRITERIA.forEach(([criterion,key]) => {
    let coef = 1;
    const pos = priorities.indexOf(criterion);
    if (pos >= 0) coef = PRIORITY_COEFS[pos];
    numerator += shoe[key] * coef;
    denominator += coef;
  });
  return (numerator / denominator) * 10;
}

function objectiveScore(shoe,p) {
  return OBJECTIVE_TYPE[p.objectif]?.[shoe.type] ?? 0;
}

function budgetScore(shoe,p) {
  const diff = shoe.prix - p.budget;
  if (diff <= 0) return 100;
  if (diff <= 10) return 90;
  if (diff <= 20) return 75;
  if (diff <= 30) return 45;
  if (diff <= 50) return 15;
  return 0;
}

function runnerWeightScore(shoe,p) {
  if (p.poids > shoe.poidsMax) return 0;
  if (p.poids >= shoe.poidsIdealMin && p.poids <= shoe.poidsIdealMax) return 100;
  const d = Math.min(Math.abs(p.poids-shoe.poidsIdealMin),Math.abs(p.poids-shoe.poidsIdealMax));
  if (d <= 5) return 90;
  if (d <= 10) return 70;
  if (d <= 15) return 40;
  return 0;
}

function distanceScore(shoe,p) {
  const d = shoe.distance;
  if (p.distance === "5 KM") {
    if (["5-21 km","5-30 km","5-42 km"].includes(d)) return 100;
    if (d === "10-42 km") return 40;
    return 0;
  }
  if (p.distance === "10 KM" || p.distance === "SEMI-MARATHON") {
    return ["5-21 km","5-30 km","5-42 km","10-42 km"].includes(d) ? 100 : 0;
  }
  if (p.distance === "MARATHON") {
    if (["5-42 km","10-42 km"].includes(d)) return 100;
    if (["5-21 km","5-30 km"].includes(d)) return 40;
  }
  return 0;
}

function footScore(shoe,p) {
  return normalizeText(shoe.typePied).includes(normalizeText(p.typePied)) ? 100 : 50;
}

function strikeScore(shoe,p) {
  if (p.attaque === "JE NE SAIS PAS") return 100;
  const attack = normalizeText(shoe.attaque);
  if (p.attaque === "MÉDIO-PIED") {
    if (attack.includes("MILIEU")) return 100;
    if (attack.includes("AVANT")) return 90;
    return 85;
  }
  if (p.attaque === "TALON") {
    if (attack.includes("TALON")) return 100;
    if (attack.includes("MILIEU")) return 80;
    return 60;
  }
  if (p.attaque === "AVANT-PIED") {
    if (attack.includes("AVANT")) return 100;
    if (attack.includes("MILIEU")) return 90;
    return 65;
  }
  return 100;
}

/* Foulée : chaussure de stabilité pour le pied qui s'affaisse vers l'intérieur (pronation),
   chaussure neutre pour une foulée neutre ou supinatrice. Une chaussure neutre très stable
   reste une option correcte pour une pronation légère. */
function pronationScore(shoe,p) {
  if (p.foulee === "PRONATION") {
    if (shoe.foulee === "STABILITÉ") return 100;
    return Math.max(0, Math.min(75, (shoe.stabilite - 7) * 25));
  }
  if (p.foulee === "NEUTRE") return shoe.foulee === "STABILITÉ" ? 60 : 100;
  if (p.foulee === "SUPINATION") return shoe.foulee === "STABILITÉ" ? 30 : 100;
  return 100;
}

function brandScore(shoe,p) {
  if (p.marque === "AUCUNE") return 100;
  return shoe.marque === p.marque ? 100 : 50;
}

function calculate(shoe,p) {
  const scores = {
    personalized: personalizedScore(shoe,p),
    objective: objectiveScore(shoe,p),
    budget: budgetScore(shoe,p),
    runnerWeight: runnerWeightScore(shoe,p),
    distance: distanceScore(shoe,p),
    foot: footScore(shoe,p),
    strike: strikeScore(shoe,p),
    brand: brandScore(shoe,p),
    foulee: pronationScore(shoe,p)
  };
  const final =
    scores.personalized * WEIGHTS.personalized +
    scores.objective * WEIGHTS.objective +
    scores.budget * WEIGHTS.budget +
    scores.runnerWeight * WEIGHTS.runnerWeight +
    scores.distance * WEIGHTS.distance +
    scores.foot * WEIGHTS.foot +
    scores.strike * WEIGHTS.strike +
    scores.brand * WEIGHTS.brand +
    scores.foulee * WEIGHTS.foulee;
  return {...shoe, scores, final, eligible:p.poids <= shoe.poidsMax};
}

function budgetLabel(shoe,p) {
  if (shoe.prix <= p.budget) return '<span class="budget-ok">'+mbpIcon("check")+' DANS LE BUDGET</span>';
  if (shoe.prix <= p.budget + 20) return '<span class="budget-heart">'+mbpIcon("heart")+' COUP DE CŒUR</span>';
  return '<span class="budget-out">'+mbpIcon("alert")+' HORS BUDGET</span>';
}

function topStrengths(shoe) {
  return CRITERIA
    .map(([label,key]) => [label,shoe[key]])
    .sort((a,b)=>b[1]-a[1])
    .slice(0,3)
    .map(x=>x[0].replace("STABILITE","STABILITÉ").replace("DURABILITE","DURABILITÉ"))
    .join(" · ");
}

function weakPoint(shoe) {
  const sorted = CRITERIA.map(([label,key])=>[label,shoe[key]]).sort((a,b)=>a[1]-b[1]);
  if (sorted[0][1] >= 7) return "";
  return sorted[0][0].replace("STABILITE","STABILITÉ").replace("DURABILITE","DURABILITÉ");
}

function priorityValue(shoe,priority) {
  const row = CRITERIA.find(([label])=>label===priority);
  return row ? shoe[row[1]] : 0;
}

function prettyCriterion(s) {
  return s.replace("STABILITE","STABILITÉ").replace("DURABILITE","DURABILITÉ");
}

function whyText(shoe,p) {
  const p1=priorityValue(shoe,p.priorite1);
  const p2=priorityValue(shoe,p.priorite2);
  const p3=priorityValue(shoe,p.priorite3);
  const avg=(p1+p2+p3)/3;
  const lead=avg>=8.5 ? "Elle correspond très bien à tes priorités" : "Elle correspond bien à tes priorités";
  return `Cette chaussure obtient ${Math.round(shoe.final)}/100 pour ton profil. ${lead} : ${prettyCriterion(p.priorite1).toLowerCase()} ${p1.toString().replace(".",",")}/10, ${prettyCriterion(p.priorite2).toLowerCase()} ${p2.toString().replace(".",",")}/10 et ${prettyCriterion(p.priorite3).toLowerCase()} ${p3.toString().replace(".",",")}/10.`;
}


